'use client';
import { useEffect, useRef, useState, type CSSProperties } from 'react';
import { useIsomorphicLayoutEffect, useScrollProgress, useStudioMotion } from '../../motion';
import type { EffectProps } from '../../types';
import styles from './styles.module.css';

type Params = { sections: number; rail: string; labels: boolean; forceFallback: boolean };
type Driver = 'css' | 'js';

/** Fraction of the container height where the "reading line" sits. Mirrored by view-timeline-inset in the CSS. */
const LINE = 0.3;

/* Sample content: a fictional essay. */
const SECTIONS: readonly { name: string; paras: readonly string[] }[] = [
  { name: 'The premise', paras: [
    'For one winter the branch library on Tannery Row stayed open until midnight, four nights a week. Nobody had asked for it. The idea came from a caretaker who noticed how many people waited outside for the doors to open at nine.',
    'The trial had no budget line of its own. It ran on rearranged shifts, one borrowed heater and a rule that the kettle stayed on.',
  ] },
  { name: 'Who came after nine', paras: [
    'Not the daytime crowd shifted later, as expected. The late hours drew people who had never held a card: night-shift cleaners between jobs, students from shared flats, a man who repaired clocks and wanted a large table.',
    'Most stayed longer than daytime visitors and borrowed less. What they were using was the room.',
  ] },
  { name: 'What it cost', paras: [
    'Heating and lighting a reading room for three extra hours is a small number. Staffing it safely is not. Two people have to be in the building, and one of them has to be willing to lock up alone.',
    'The honest figure included taxis home, which no spreadsheet had a column for.',
  ] },
  { name: 'What changed', paras: [
    'The noise rules went first. A room that is half empty at eleven at night polices itself, and the staff stopped shushing within a fortnight.',
    'The second change was the shelving. Reference books nobody touched by day were pulled toward the big tables, where the night readers actually sat.',
  ] },
  { name: 'What stayed', paras: [
    'When the trial ended, two late nights were kept. The heater went back. The kettle rule, never written down, survived intact.',
    'A handwritten sign by the returns desk still reads: after nine, sit anywhere.',
  ] },
  { name: 'Open questions', paras: [
    'Whether the late readers would come in summer is not known. Nor is whether a quieter building changes who feels welcome in it by day.',
    'Both would take another winter to answer, and somebody willing to lock up.',
  ] },
];

const NEXT = ['The ferry timetable as a public document', 'Seven benches, measured', 'Why the market moved indoors'];

const pad = (n: number): string => String(n).padStart(2, '0');

export default function ScrollProgressRail({ params }: EffectProps<Params>) {
  const scroller = useRef<HTMLDivElement>(null);
  const layout = useRef<HTMLDivElement>(null);
  const pct = useRef<HTMLSpanElement>(null);
  const { reduced } = useStudioMotion();
  const [driver, setDriver] = useState<Driver>('css');
  const [supported, setSupported] = useState(true);
  const [current, setCurrent] = useState(-1);

  const count = Math.min(SECTIONS.length, Math.max(3, Math.round(params.sections)));
  const sections = SECTIONS.slice(0, count);

  // Feature detection: both the scroll-driven timeline and timeline-scope are needed for the CSS driver.
  useIsomorphicLayoutEffect(() => {
    const ok = typeof CSS !== 'undefined' && CSS.supports('animation-timeline: scroll()') && CSS.supports('timeline-scope: --a');
    setSupported(ok);
    setDriver(ok && !params.forceFallback ? 'css' : 'js');
  }, [params.forceFallback]);

  // Fallback driver: one rAF-batched callback → read every rect, then write every property.
  useScrollProgress(
    layout,
    (p) => {
      const sc = scroller.current;
      const root = layout.current;
      if (!sc || !root) return;
      const line = sc.getBoundingClientRect().top + sc.clientHeight * LINE;
      const marks = root.querySelectorAll<HTMLElement>('[data-mark]');
      const fills = Array.from(root.querySelectorAll<HTMLElement>('[data-sec]'), (el) => {
        const r = el.getBoundingClientRect();
        return Math.min(1, Math.max(0, (line - r.top) / r.height));
      });
      fills.forEach((f, i) => marks[i]?.style.setProperty('--seg', f.toFixed(4)));
      pct.current?.style.setProperty('--spr-pct', String(Math.round(p * 100)));
    },
    { container: scroller, mode: 'contain', enabled: driver === 'js' },
  );
  // Leaving the fallback: drop the inline properties so the CSS timelines own them again.
  useEffect(() => {
    if (driver !== 'js') return;
    const root = layout.current;
    const readout = pct.current;
    return () => {
      root?.querySelectorAll<HTMLElement>('[data-mark]').forEach((m) => m.style.removeProperty('--seg'));
      readout?.style.removeProperty('--spr-pct');
    };
  }, [driver, count]);

  // ARIA state cannot come from CSS: observe which section crosses the reading line.
  useEffect(() => {
    const sc = scroller.current;
    if (!sc || typeof IntersectionObserver === 'undefined') return;
    const on = new Set<number>();
    const io = new IntersectionObserver(
      (entries) => {
        for (const e of entries) {
          const i = Number((e.target as HTMLElement).dataset.sec);
          if (e.isIntersecting) on.add(i); else on.delete(i);
        }
        setCurrent(on.size ? Math.max(...on) : -1);
      },
      { root: sc, rootMargin: `-${LINE * 100}% 0px -${(1 - LINE) * 100 - 1}% 0px` },
    );
    sc.querySelectorAll('[data-sec]').forEach((el) => io.observe(el));
    return () => io.disconnect();
  }, [count]);

  const goTo = (i: number): void => {
    const sc = scroller.current;
    const el = sc?.querySelector<HTMLElement>(`[data-sec="${i}"]`);
    if (!sc || !el) return;
    const top = el.getBoundingClientRect().top - sc.getBoundingClientRect().top + sc.scrollTop;
    // Land the heading just above the reading line so the section is unambiguously current.
    sc.scrollTo({ top: Math.max(0, top - sc.clientHeight * (LINE - 0.12)), behavior: reduced ? 'auto' : 'smooth' });
    el.querySelector<HTMLElement>('h3')?.focus({ preventScroll: true });
  };

  const driverLabel = driver === 'css' ? 'CSS scroll-timeline' : supported ? 'JS fallback (forced)' : 'JS fallback (no animation-timeline)';

  return (
    <div className={styles.root} data-driver={driver} data-rail={params.rail === 'top' ? 'top' : 'side'} data-labels={params.labels ? 'on' : 'off'}>
      <div ref={scroller} className={styles.scroller} tabIndex={0} role="region" aria-label="Sample article with a reading-progress rail — scroll to read">
        <div ref={layout} className={styles.layout} style={{ '--count': count } as CSSProperties}>
          <nav className={styles.rail} aria-label="Sections">
            <p className={styles.railHead}>
              <span>Reading</span>
              <span ref={pct} className={styles.pct} aria-hidden="true" />
            </p>
            <ol className={styles.marks}>
              {sections.map((s, i) => (
                <li key={s.name} className={styles.mark} data-mark={i}>
                  <button type="button" className={styles.markBtn} aria-current={current === i ? 'location' : undefined} onClick={() => goTo(i)}>
                    <span className={styles.seg} aria-hidden="true" />
                    {/* Visible text is the accessible name (WCAG 2.5.3 Label in Name). */}
                    <span className={styles.idx}>{pad(i + 1)}</span>
                    <span className={styles.name}>{s.name}</span>
                  </button>
                </li>
              ))}
            </ol>
            <p className={styles.driver}><span className={styles.driverKey}>Driver</span> {driverLabel}</p>
          </nav>

          <article className={styles.article}>
            <header className={styles.lead}>
              <p className={styles.label}>Essay · sample content</p>
              <h2 className={styles.heading}>The library that kept its lights on</h2>
              <p className={styles.standfirst}>A winter of late opening on Tannery Row, and what a reading room is for after dark.</p>
            </header>
            {sections.map((s, i) => (
              <section key={s.name} className={styles.section} data-sec={i} aria-labelledby={`spr-h-${i}`}>
                <h3 id={`spr-h-${i}`} className={styles.h3} tabIndex={-1}><span className={styles.h3Idx} aria-hidden="true">{pad(i + 1)}</span>{s.name}</h3>
                {s.paras.map((p) => <p key={p.slice(0, 24)}>{p}</p>)}
              </section>
            ))}
            <footer className={styles.colophon}>
              <p className={styles.label}>Next in this issue</p>
              <ul className={styles.next}>
                {NEXT.map((n, i) => <li key={n}><span aria-hidden="true">{pad(i + 1)}</span>{n}</li>)}
              </ul>
              <p className={styles.fine}>All people, places and events in this sample are fictional.</p>
            </footer>
          </article>
        </div>
      </div>
    </div>
  );
}

@property --spr-pct { syntax: '<integer>'; inherits: false; initial-value: 0; }

.root {
  --h: 560px;
  --line: 30%;
  position: relative;
  justify-self: stretch;
  inline-size: 100%;
  block-size: var(--h);
  container-type: inline-size;
  color: var(--mk-ink, #11110f);
  font-family: var(--mk-font-text, ui-sans-serif, system-ui, sans-serif);
  text-align: start;
}
.scroller {
  position: absolute;
  inset: 0;
  overflow-y: auto;
  scrollbar-width: thin;
  scrollbar-color: var(--mk-line, #11110f24) transparent;
}
.scroller:focus-visible { outline: 2px solid var(--mk-focus, #1d4ed8); outline-offset: -2px; }

.layout {
  display: grid;
  grid-template-columns: 232px minmax(0, 1fr);
  /* lets the markers (outside the sections) subscribe to each section's view timeline */
  timeline-scope: --spr-0, --spr-1, --spr-2, --spr-3, --spr-4, --spr-5;
}

/* ── Rail ─────────────────────────────────────────────────────────────── */
.rail {
  position: sticky;
  inset-block-start: 0;
  display: grid;
  grid-template-rows: auto minmax(0, 1fr) auto;
  gap: 20px;
  block-size: var(--h);
  padding: 36px 20px 28px 32px;
  border-inline-end: 1px solid var(--mk-line, #11110f24);
}
.railHead, .driver, .label, .fine {
  margin: 0;
  font-family: var(--mk-font-mono, ui-monospace, monospace);
  font-size: 0.6875rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--mk-ink-muted, #5c5a52);
}
.railHead { display: flex; justify-content: space-between; align-items: baseline; }
.pct { counter-reset: spr-pct var(--spr-pct); color: var(--mk-ink, #11110f); font-variant-numeric: tabular-nums; }
.pct::after { content: counter(spr-pct) '%'; }
.driver { font-size: 0.625rem; line-height: 1.5; text-wrap: balance; }
.driverKey { display: block; color: var(--mk-ink-muted, #5c5a52); }

.marks { display: grid; grid-auto-rows: minmax(0, 1fr); gap: 6px; margin: 0; padding: 0; list-style: none; }
.mark { --seg: 0; display: grid; min-block-size: 0; }
.markBtn {
  display: grid;
  grid-template-columns: 2px auto minmax(0, 1fr);
  align-items: start;
  column-gap: 12px;
  min-block-size: 28px;
  padding: 0;
  border: 0;
  background: none;
  font: inherit;
  font-size: 0.875rem;
  line-height: 1.25;
  text-align: start;
  color: var(--mk-ink-muted, #5c5a52);
  cursor: pointer;
  transition: color var(--mk-duration-fast, 160ms) linear;
}
.markBtn:hover { color: var(--mk-ink, #11110f); }
.markBtn:focus-visible { outline: 2px solid var(--mk-focus, #1d4ed8); outline-offset: 3px; border-radius: 2px; }
.seg { position: relative; align-self: stretch; background: var(--mk-line, #11110f24); border-radius: 2px; overflow: clip; }
.seg::after {
  content: '';
  position: absolute;
  inset: 0;
  background: var(--mk-signal, #bf2f09);
  transform-origin: 0 0;
  scale: 1 var(--seg);
}
.idx { font-family: var(--mk-font-mono, ui-monospace, monospace); font-size: 0.6875rem; letter-spacing: 0.06em; padding-block-start: 0.2em; }
.name { text-wrap: balance; }
.root[data-labels='off'] .name { display: none; }
.markBtn[aria-current] { color: var(--mk-ink, #11110f); }
.markBtn[aria-current] .name { font-weight: 600; }

/* ── CSS driver: scroll-driven animations ─────────────────────────────── */
@supports (animation-timeline: scroll()) {
  .root[data-driver='css'] .pct { animation: spr-count linear both; animation-timeline: scroll(nearest block); }
  .root[data-driver='css'] .section { view-timeline-axis: block; view-timeline-inset: var(--line) calc(99% - var(--line)); }
  .root[data-driver='css'] .section[data-sec='0'] { view-timeline-name: --spr-0; }
  .root[data-driver='css'] .section[data-sec='1'] { view-timeline-name: --spr-1; }
  .root[data-driver='css'] .section[data-sec='2'] { view-timeline-name: --spr-2; }
  .root[data-driver='css'] .section[data-sec='3'] { view-timeline-name: --spr-3; }
  .root[data-driver='css'] .section[data-sec='4'] { view-timeline-name: --spr-4; }
  .root[data-driver='css'] .section[data-sec='5'] { view-timeline-name: --spr-5; }
  .root[data-driver='css'] .mark[data-mark='0'] { --tl: --spr-0; }
  .root[data-driver='css'] .mark[data-mark='1'] { --tl: --spr-1; }
  .root[data-driver='css'] .mark[data-mark='2'] { --tl: --spr-2; }
  .root[data-driver='css'] .mark[data-mark='3'] { --tl: --spr-3; }
  .root[data-driver='css'] .mark[data-mark='4'] { --tl: --spr-4; }
  .root[data-driver='css'] .mark[data-mark='5'] { --tl: --spr-5; }
  /* fill: 0 before the section reaches the line, 1 after it has passed (fill-mode both) */
  .root[data-driver='css'] .seg::after { animation: spr-fill-y linear both; animation-timeline: var(--tl); }
}
@keyframes spr-count { from { --spr-pct: 0; } to { --spr-pct: 100; } }
@keyframes spr-fill-y { from { scale: 1 0; } to { scale: 1 1; } }
@keyframes spr-fill-x { from { scale: 0 1; } to { scale: 1 1; } }

/* ── Article ──────────────────────────────────────────────────────────── */
.article { padding: 0 clamp(20px, 6cqi, 56px); max-inline-size: 40rem; }
.lead { display: grid; align-content: end; gap: 10px; min-block-size: calc(var(--h) * 0.36); padding-block: 36px 28px; }
.heading {
  margin: 0;
  font-family: var(--mk-font-display, ui-sans-serif, system-ui, sans-serif);
  font-size: clamp(1.75rem, 5.6cqi, 2.75rem);
  font-weight: 700;
  line-height: 1;
  letter-spacing: -0.035em;
  text-wrap: balance;
}
.standfirst {
  margin: 0;
  font-family: var(--mk-font-serif, Georgia, serif);
  font-size: 1.25rem;
  font-style: italic;
  line-height: 1.25;
  color: var(--mk-ink-muted, #5c5a52);
  text-wrap: pretty;
}
.section { padding-block: 28px 32px; border-block-start: 1px solid var(--mk-line, #11110f24); font-size: 1rem; line-height: 1.6; }
.section p { margin: 0; text-wrap: pretty; }
.section p + p { margin-block-start: 0.9em; }
.h3 {
  display: flex;
  align-items: baseline;
  gap: 12px;
  margin: 0 0 14px;
  font-family: var(--mk-font-display, ui-sans-serif, system-ui, sans-serif);
  font-size: 1.375rem;
  font-weight: 650;
  letter-spacing: -0.02em;
  line-height: 1.15;
  outline: none;
}
.h3:focus-visible { outline: 2px solid var(--mk-focus, #1d4ed8); outline-offset: 4px; border-radius: 2px; }
.h3Idx { font-family: var(--mk-font-mono, ui-monospace, monospace); font-size: 0.6875rem; font-weight: 400; letter-spacing: 0.08em; color: var(--mk-signal, #bf2f09); }
.colophon {
  display: grid;
  align-content: start;
  gap: 16px;
  min-block-size: calc(var(--h) * 0.72);
  padding-block: 28px 40px;
  border-block-start: 1px solid var(--mk-line-strong, #11110f);
}
.next { display: grid; margin: 0; padding: 0; list-style: none; }
.next li {
  display: flex;
  align-items: baseline;
  gap: 14px;
  padding-block: 12px;
  border-block-end: 1px solid var(--mk-line, #11110f24);
  font-family: var(--mk-font-display, ui-sans-serif, system-ui, sans-serif);
  font-size: 1.125rem;
  font-weight: 600;
  letter-spacing: -0.015em;
}
.next span { font-family: var(--mk-font-mono, ui-monospace, monospace); font-size: 0.6875rem; font-weight: 400; color: var(--mk-ink-muted, #5c5a52); }
.fine { text-transform: none; letter-spacing: 0.02em; }

/* ── Top rail (param, or automatically in narrow containers) ──────────── */
.root[data-rail='top'] .layout { grid-template-columns: minmax(0, 1fr); }
.root[data-rail='top'] .article { margin-inline: auto; }
.root[data-rail='top'] .rail {
  z-index: 1;
  grid-template-columns: minmax(0, 1fr) auto;
  grid-template-rows: auto auto;
  gap: 10px 16px;
  block-size: auto;
  padding: 14px clamp(20px, 6cqi, 56px) 12px;
  border-inline-end: 0;
  border-block-end: 1px solid var(--mk-line, #11110f24);
  background: var(--mk-surface, #fbf9f4);
}
.root[data-rail='top'] .marks { position: relative; grid-column: 1 / -1; grid-row: 1; grid-auto-flow: column; grid-auto-columns: minmax(0, 1fr); grid-auto-rows: auto; gap: 4px; padding-block-end: 22px; }
.root[data-rail='top'] .markBtn { display: block; inline-size: 100%; min-block-size: 24px; padding-block: 10px; }
.root[data-rail='top'] .seg { display: block; block-size: 3px; }
.root[data-rail='top'] .seg::after { scale: var(--seg) 1; }
.root[data-rail='top'] .idx { display: none; }
.root[data-rail='top'] .name {
  position: absolute;
  inset-inline-start: 0;
  inset-block-end: 0;
  display: block;
  max-inline-size: 100%;
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
  opacity: 0;
  pointer-events: none;
  transition: opacity var(--mk-duration-fast, 160ms) linear;
}
.root[data-rail='top'] .markBtn[aria-current] .name { opacity: 1; }
.root[data-rail='top'] .railHead { grid-column: 2; grid-row: 2; }
.root[data-rail='top'] .railHead > :first-child { display: none; }
.root[data-rail='top'] .driver { grid-column: 1; grid-row: 2; }
.root[data-rail='top'] .driverKey { display: inline; }
.root[data-rail='top'] .lead { min-block-size: calc(var(--h) * 0.2); }
@supports (animation-timeline: scroll()) {
  .root[data-driver='css'][data-rail='top'] .seg::after { animation-name: spr-fill-x; }
}

@container (max-width: 620px) {
  .layout { grid-template-columns: minmax(0, 1fr); }
  .rail {
    z-index: 1;
    grid-template-columns: minmax(0, 1fr) auto;
    grid-template-rows: auto auto;
    gap: 10px 16px;
    block-size: auto;
    padding: 14px 20px 12px;
    border-inline-end: 0;
    border-block-end: 1px solid var(--mk-line, #11110f24);
    background: var(--mk-surface, #fbf9f4);
  }
  .marks { position: relative; grid-column: 1 / -1; grid-row: 1; grid-auto-flow: column; grid-auto-columns: minmax(0, 1fr); grid-auto-rows: auto; gap: 4px; padding-block-end: 22px; }
  .markBtn { display: block; inline-size: 100%; min-block-size: 24px; padding-block: 10px; }
  .seg { display: block; block-size: 3px; }
  .seg::after { scale: var(--seg) 1; }
  .idx { display: none; }
  .name {
    position: absolute;
    inset-inline-start: 0;
    inset-block-end: 0;
    display: block;
    max-inline-size: 100%;
    overflow: hidden;
    white-space: nowrap;
    text-overflow: ellipsis;
    opacity: 0;
    pointer-events: none;
    transition: opacity var(--mk-duration-fast, 160ms) linear;
  }
  .markBtn[aria-current] .name { opacity: 1; }
  .railHead { grid-column: 2; grid-row: 2; }
  .railHead > :first-child { display: none; }
  .driver { grid-column: 1; grid-row: 2; }
  .driverKey { display: inline; }
  .lead { min-block-size: calc(var(--h) * 0.2); }
  .section { font-size: 0.9375rem; }
  @supports (animation-timeline: scroll()) {
    .root[data-driver='css'] .seg::after { animation-name: spr-fill-x; }
  }
}
@media (prefers-reduced-motion: reduce) {
  .markBtn, .name { transition: none; }
}
